final class ZSTD_Sequence extends ffi.Struct {
  /// The offset of the match. (NOT the same as the offset code)
  /// If offset == 0 and matchLength == 0, this sequence represents the last
  /// literals in the block of litLength size.
  @ffi.UnsignedInt()
  external int offset;

  /// Literal length of the sequence.
  @ffi.UnsignedInt()
  external int litLength;

  /// Match length of the sequence.
  @ffi.UnsignedInt()
  external int matchLength;

  /// Represents which repeat offset is represented by the field 'offset'.
  /// Ranges from [0, 3].
  ///
  /// Repeat offsets are essentially previous offsets from previous sequences sorted in
  /// recency order. For more detail, see doc/zstd_compression_format.md
  ///
  /// If rep == 0, then 'offset' does not contain a repeat offset.
  /// If rep > 0:
  /// If litLength != 0:
  /// rep == 1 --> offset == repeat_offset_1
  /// rep == 2 --> offset == repeat_offset_2
  /// rep == 3 --> offset == repeat_offset_3
  /// If litLength == 0:
  /// rep == 1 --> offset == repeat_offset_2
  /// rep == 2 --> offset == repeat_offset_3
  /// rep == 3 --> offset == repeat_offset_1 - 1
  ///
  /// Note: This field is optional. ZSTD_generateSequences() will calculate the value of
  /// 'rep', but repeat offsets do not necessarily need to be calculated from an external
  /// sequence provider perspective. For example, ZSTD_compressSequences() does not
  /// use this 'rep' field at all (as of now).
  @ffi.UnsignedInt()
  external int rep;
}

final class ZSTD_compressionParameters extends ffi.Struct {
  /// < largest match distance : larger == more compression, more memory needed during decompression
  @ffi.UnsignedInt()
  external int windowLog;

  /// < fully searched segment : larger == more compression, slower, more memory (useless for fast)
  @ffi.UnsignedInt()
  external int chainLog;

  /// < dispatch table : larger == faster, more memory
  @ffi.UnsignedInt()
  external int hashLog;

  /// < nb of searches : larger == more compression, slower
  @ffi.UnsignedInt()
  external int searchLog;

  /// < match length searched : larger == faster decompression, sometimes less compression
  @ffi.UnsignedInt()
  external int minMatch;

  /// < acceptable match size for optimal parser (only) : larger == more compression, slower
  @ffi.UnsignedInt()
  external int targetLength;

  /// < see ZSTD_strategy definition above
  @ffi.UnsignedInt()
  external int strategyAsInt;

  ZSTD_strategy get strategy => ZSTD_strategy.fromValue(strategyAsInt);
}

final class ZSTD_frameParameters extends ffi.Struct {
  /// < 1: content size will be in frame header (when known)
  @ffi.Int()
  external int contentSizeFlag;

  /// < 1: generate a 32-bits checksum using XXH64 algorithm at end of frame, for error detection
  @ffi.Int()
  external int checksumFlag;

  /// < 1: no dictID will be saved into frame header (dictID is only useful for dictionary compression)
  @ffi.Int()
  external int noDictIDFlag;
}

final class ZSTD_parameters extends ffi.Struct {
  external ZSTD_compressionParameters cParams;

  external ZSTD_frameParameters fParams;
}

enum ZSTD_dictContentType_e {
  /// dictionary is "full" when starting with ZSTD_MAGIC_DICTIONARY, otherwise it is "rawContent"
  ZSTD_dct_auto(0),

  /// ensures dictionary is always loaded as rawContent, even if it starts with ZSTD_MAGIC_DICTIONARY
  ZSTD_dct_rawContent(1),

  /// refuses to load a dictionary if it does not respect Zstandard's specification, starting with ZSTD_MAGIC_DICTIONARY
  ZSTD_dct_fullDict(2);

  final int value;
  const ZSTD_dictContentType_e(this.value);

  static ZSTD_dictContentType_e fromValue(int value) => switch (value) {
    0 => ZSTD_dct_auto,
    1 => ZSTD_dct_rawContent,
    2 => ZSTD_dct_fullDict,
    _ => throw ArgumentError(
      'Unknown value for ZSTD_dictContentType_e: $value',
    ),
  };
}

enum ZSTD_dictLoadMethod_e {
  /// < Copy dictionary content internally
  ZSTD_dlm_byCopy(0),

