  const ZSTD_dictLoadMethod_e(this.value);

  static ZSTD_dictLoadMethod_e fromValue(int value) => switch (value) {
    0 => ZSTD_dlm_byCopy,
    1 => ZSTD_dlm_byRef,
    _ => throw ArgumentError('Unknown value for ZSTD_dictLoadMethod_e: $value'),
  };
}

enum ZSTD_format_e {
