final class ZSTD_FrameHeader extends ffi.Struct {
  /// if == ZSTD_CONTENTSIZE_UNKNOWN, it means this field is not available. 0 means "empty"
  @ffi.UnsignedLongLong()
  external int frameContentSize;

  /// can be very large, up to <= frameContentSize
  @ffi.UnsignedLongLong()
  external int windowSize;

  @ffi.UnsignedInt()
  external int blockSizeMax;

  /// if == ZSTD_skippableFrame, frameContentSize is the size of skippable content
  @ffi.UnsignedInt()
  external int frameTypeAsInt;

  ZSTD_FrameType_e get frameType => ZSTD_FrameType_e.fromValue(frameTypeAsInt);

  @ffi.UnsignedInt()
  external int headerSize;

  /// for ZSTD_skippableFrame, contains the skippable magic variant [0-15]
  @ffi.UnsignedInt()
  external int dictID;

  @ffi.UnsignedInt()
  external int checksumFlag;

  @ffi.UnsignedInt()
  external int _reserved1;

  @ffi.UnsignedInt()
  external int _reserved2;
}

