typedef ZSTD_allocFunctionFunction =
    ffi.Pointer<ffi.Void> Function(ffi.Pointer<ffi.Void> opaque, ffi.Size size);
typedef DartZSTD_allocFunctionFunction =
    ffi.Pointer<ffi.Void> Function(ffi.Pointer<ffi.Void> opaque, int size);

/// ! Custom memory allocation :
/// These prototypes make it possible to pass your own allocation/free functions.
/// ZSTD_customMem is provided at creation time, using ZSTD_create*_advanced() variants listed below.
/// All allocation/free operations will be completed using these custom variants instead of regular <stdlib.h> ones.
typedef ZSTD_allocFunction =
    ffi.Pointer<ffi.NativeFunction<ZSTD_allocFunctionFunction>>;
typedef ZSTD_freeFunctionFunction =
    ffi.Void Function(
      ffi.Pointer<ffi.Void> opaque,
      ffi.Pointer<ffi.Void> address,
    );
typedef DartZSTD_freeFunctionFunction =
    void Function(ffi.Pointer<ffi.Void> opaque, ffi.Pointer<ffi.Void> address);
typedef ZSTD_freeFunction =
    ffi.Pointer<ffi.NativeFunction<ZSTD_freeFunctionFunction>>;

final class ZSTD_customMem extends ffi.Struct {
  external ZSTD_allocFunction customAlloc;

  external ZSTD_freeFunction customFree;

  external ffi.Pointer<ffi.Void> opaque;
}

final class POOL_ctx_s extends ffi.Opaque {}

/// ! Thread pool :
/// These prototypes make it possible to share a thread pool among multiple compression contexts.
/// This can limit resources for applications with multiple threads where each one uses
/// a threaded compression mode (via ZSTD_c_nbWorkers parameter).
/// ZSTD_createThreadPool creates a new thread pool with a given number of threads.
/// Note that the lifetime of such pool must exist while being used.
/// ZSTD_CCtx_refThreadPool assigns a thread pool to a context (use NULL argument value
/// to use an internal thread pool).
/// ZSTD_freeThreadPool frees a thread pool, accepts NULL pointer.
typedef ZSTD_threadPool = POOL_ctx_s;

final class ZSTD_frameProgression extends ffi.Struct {
  /// nb input bytes read and buffered
  @ffi.UnsignedLongLong()
  external int ingested;

  /// nb input bytes actually compressed
  @ffi.UnsignedLongLong()
  external int consumed;

  /// nb of compressed bytes generated and buffered
  @ffi.UnsignedLongLong()
  external int produced;

  /// nb of compressed bytes flushed : not provided; can be tracked from caller side
  @ffi.UnsignedLongLong()
  external int flushed;

  /// MT only : latest started job nb
  @ffi.UnsignedInt()
  external int currentJobID;

  /// MT only : nb of workers actively compressing at probe time
  @ffi.UnsignedInt()
  external int nbActiveWorkers;
}

